   x.fillStyle='#ff0000';x.beginPath();x.moveTo(23,29);x.bezierCurveTo(13,22,15,14,19.5,15.5);x.bezierCurveTo(21.5,16.2,23,18,23,18);x.bezierCurveTo(23,18,24.5,16.2,26.5,15.5);x.bezierCurveTo(31,14,33,22,23,29);x.fill();
