const PLAY_ORES=['iron','silica','thorium','sulfur','copper','aluminum','titanium','uranium','platinum'];
function drawOre(o){return x=>{const [li,mi,dk,fl]=o.ic,pts=[];const n=9;
  for(let i=0;i<n;i++){const a=Math.PI+i/n*Math.PI*2,r=.78+hash(i,o.seed)*.27;pts.push([16+Math.cos(a)*13.5*r,18+Math.sin(a)*10.5*r]);if(pts[i][1]>28)pts[i][1]=28}
  poly(x,pts,LG(x,5,7,27,28,li,mi,mi,dk));
  poly(x,[[15,17],pts[0],pts[1],pts[2],pts[3]],LG(x,4,8,16,18,li,mi));
  poly(x,[[15,17],pts[5],pts[6],pts[7]],dk);
  line(x,[[15,17],pts[1]],'rgba(255,255,255,.7)');line(x,[[15,17],pts[5]],'rgba(0,0,0,.6)');
  if(o.crystal){[[11,17,3,9,-.2],[16,15,3.5,12,.05],[21,17,2.6,8,.35]].forEach(([cx,b,w,h,rt])=>{x.save();x.translate(cx,b);x.rotate(rt);
    poly(x,[[-w,0],[-w,-h],[0,-h-3],[w,-h],[w,0]],LG(x,-w,0,w,0,'#ffffff',o.crystal,'#808080'));line(x,[[0,-h-3],[0,0]],'rgba(255,255,255,.8)');x.restore()})}
  x.save();x.beginPath();pts.forEach(([a,b],i)=>i?x.lineTo(a,b):x.moveTo(a,b));x.closePath();x.clip();
  for(let i=0;i<9;i++){const fx=6+hash(i,o.seed+5)*20,fy=12+hash(i,o.seed+9)*14;x.fillStyle=fl;x.fillRect(Math.round(fx),Math.round(fy),2,2);x.fillStyle='#ffffff';if(i%3===0)x.fillRect(Math.round(fx),Math.round(fy),1,1)}
  x.restore()}}
for(const k in ORES){ORES[k].i32=mk(drawOre(ORES[k]),32);ORES[k].i16=mk(drawOre(ORES[k]),16)}
