const TAB_NAMES=[['craft','Crafting Station'],['power','Solar Array'],['mine','Mine'],['terra','Terraform'],['launch','Launch Pad'],['hydro','Hydro'],['bio','Biolab']];
const HELP_ITEMS=[['Ask Sprocket for a hint','spr:ask'],['Tour with Sprocket','spr:tour'],['Mission Briefing','brief','F1']];
const MENUS=[
 ['File',()=>RELEASE?[['New Game…','newgame']]:[['New Game…','newgame'],['Save Game','save','Ctrl+S'],['Load Game','loadgame'],'-',['Exit','',null,true]]],
 ['View',()=>TAB_NAMES.filter(([t])=>!tabOpen[t]||tabOpen[t]()).map(([t,n])=>[n,'tab:'+t])],
 ['Colony',()=>[['Mission Briefing','brief']]],
 ['Build',()=>BLUEPRINTS.filter(b=>!b.prebuilt&&!(FAB_IN_TAB&&b.id==='fab')&&(S.built[b.id]||b.avail())).map(b=>[b.name,'bp:'+b.id])],
 ['Options',()=>[['Toggle CRT Lines','crt'],'-',[`${audOn('music')?'✓ ':''}Music`,'snd:music'],[`${audOn('sfx')?'✓ ':''}Sound Effects`,'snd:sfx']]],
 ['Debug',()=>[['Dev Kit…','devkit'],['Mini-Game Playground…','playground'],['+500 Resources','dev:res'],['Complete Stage','dev:stage'],'-',['Speed ×1','dev:s1'],['Speed ×5','dev:s5'],['Speed ×20','dev:s20'],'-',['Layout: Big resource list','ui:lay:big'],['Layout: Classic panels','ui:lay:classic'],'-',['Locked items: show as ???','ui:lk:mystery'],['Locked items: hide','ui:lk:hide'],'-',[`${FG?'✓ ':''}Full game preview: automation`,'dev:fg'],'-',[`${DEMO?'✓ ':''}Demo mode (Not in demo locks)`,'demotoggle'],['Export itch.io build…','itch']]],
 ['Help',()=>HELP_ITEMS]
];
if(RELEASE)MENUS.splice(MENUS.findIndex(m=>m[0]==='Debug'),1);   // the public build has no Debug menu
const menuItems=items=>items.map(it=>it==='-'?'<hr>':`<button role="menuitem" data-act="mi" data-id="${it[1]}" ${it[3]?'disabled':''}><span>${it[0]}</span><span>${it[2]||''}</span></button>`).join('');
$('#menubar').innerHTML=MENUS.map(([n],i)=>`<div class="menu" data-m="${i}"><button data-act="menu" data-id="${i}" aria-haspopup="menu"><u>${n[0]}</u>${n.slice(1)}</button>
  <div class="drop win" role="menu" hidden></div></div>`).join('');
function closeMenus(){$$('.menu').forEach(m=>{m.classList.remove('open');m.querySelector('.drop').hidden=true});const hm=$('#tl-helpmenu');if(hm)hm.hidden=true}

document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');const sm=$('#startmenu');
  if(!t){if(!e.target.closest('#startmenu'))sm.hidden=true;if(!e.target.closest('.menu'))closeMenus();return}
  let a=t.dataset.act,id=t.dataset.id;const fromMenu=a==='mi';if(a!=='start')sm.hidden=true;const hmWas=!$('#tl-helpmenu').hidden;if(a!=='menu')closeMenus();
  if(a==='mi'){if(!id)return;const i=id.indexOf(':');if(i>0){a=id.slice(0,i);id=id.slice(i+1)}else a=id}
  switch(a){
   case 'menu':{const m=t.parentElement,open=m.classList.contains('open');closeMenus();if(!open){m.querySelector('.drop').innerHTML=menuItems(MENUS[+id][1]());m.classList.add('open');m.querySelector('.drop').hidden=false}break}
   case 'helpmenu':{const hm=$('#tl-helpmenu');if(hmWas)break;const r=t.getBoundingClientRect();hm.innerHTML=menuItems(HELP_ITEMS);hm.style.left=r.left/RZ+'px';hm.style.top=r.bottom/RZ+'px';hm.hidden=false;break}
   case 'tab':setTab(id);break;
   case 'spr':HELPER.act(id,t);break;
   case 'bp':{const b0=BP(id);if(b0&&!(b0.prebuilt||S.built[b0.id]||b0.avail()))break}S.bpSel=id;if(S.tab!=='craft')setTab('craft');renderAll();break;
   case 'build':build(id);break;case 'craft':craft(id);break;case 'upg':buyUpg(id);break;
   case 'ore':S.sel=id;renderMine();break;case 'mine':mine(e);break;
   case 'tview':S.tview=id;renderTerra();break;
   case 'mtoggle':mtoggle();break;case 'load':loadFuel(id);break;
   case 'ptoggle':S.pump.on=!S.pump.on;renderHydro();break;case 'flush':if(S.energy>=1){S.energy-=1;S.pump.filter=100;log('Intake filters flushed.','w')}renderHydro();break;
   case 'crank':crank();break;
   case 'seedsel':if(S.sprink.seed!==id){S.inv[S.sprink.seed]+=S.sprink.hop;S.sprink.hop=0;S.sprink.seed=id}renderTerra();break;
   case 'hopper':{const n=Math.min(5,20-S.sprink.hop,have(S.sprink.seed));if(n>0){S.inv[S.sprink.seed]-=n;S.sprink.hop+=n}renderTerra();break}
   case 'splice':{const [i,k]=id.split(':');startSplice(+i,k);break}
   case 'base':spliceInput(id);break;case 'spcancel':S.splice=null;renderBio();break;
   case 'wtray':waterTray(+id);renderBio();break;
   case 'uproot':{const t=S.trays[+id];if(t){t.type=null;t.t=0;t.m=100}renderBio();break}
   case 'autosel':S.bio.auto=id;renderBio();break;
   case 'harvest':harvest(S.trays[+id]);renderBio();break;
   case 'lbegin':lbegin();break;case 'lcheck':lcheck(+id);break;case 'lignite':lignite();break;case 'lcorrect':lcorrect();break;
   case 'seed':plantSeed();break;
   case 'decode':startDecode(id);break;case 'dbase':decodeInput(id);break;case 'deccancel':{const l=L_();if(l.dec){log('Decode aborted. Uranium Cells spent.','a');l.dec=null}renderAll();break}
   case 'incubate':incubate(id);break;case 'release':release(+id);break;
   case 'itch':if(!RELEASE)itchDialog();break;
   case 'demotoggle':if(!RELEASE)dialog({title:'Demo mode',icon:URL_.dev,html:`<p>Demo mode is <b>${DEMO?'ON':'OFF'}</b>. ${DEMO?'Switch it off to test the full game: everything after Stage 3 unlocks normally and nothing says "Not in demo".':'Switch it back on to get the demo locks again.'}</p><p>The page reloads to apply it. The itch.io export is always the demo.</p>`,buttons:[{label:DEMO?'Turn demo mode OFF':'Turn demo mode ON',fn:()=>{UI.demo=!DEMO;saveUI();location.reload()}},{label:'Cancel'}]});break;
   case 'devkit':if(!RELEASE)devkit();break;case 'exp':exportRun(id);break;case 'playground':if(!RELEASE)playground();break;case 'play':if(!RELEASE)enterPlay(id);break;case 'exitplay':exitPlay();break;case 'dev':if(!RELEASE)dev(id);break;
   case 'start':sm.hidden=!sm.hidden;break;
   case 'wishlist':openWishlist();break;   case 'brief':intro();break;case 'reports':reports();break;
   case 'save':{if(RELEASE)break;if(PLAY){log('Playground is never saved. Exit to return to your colony.','a');break}const ok=save();log(ok?'Game saved.':'Save failed: browser storage unavailable.',ok?'g':'r');break}
   case 'loadgame':{if(RELEASE)break;if(load()){for(const k in sigs)delete sigs[k];renderLog();renderOut();renderAll();log('Save loaded.','g')}else log('No saved game found.','a');break}
   case 'ui':{const [k,v]=id.split(':');UI[k]=v;saveUI();for(const q in sigs)delete sigs[q];applyLayout();renderAll();log(k==='lay'?`Layout: ${v==='classic'?'Classic panels':'Big resource list'}.`:`Locked items: ${v==='hide'?'hidden':'shown as ???'}.`,'c');break}
   case 'snd':UI[id]=!audOn(id);saveUI();if(id==='music')musicSync();else sfx('click');break;
    case 'crt':S.crt=!S.crt;document.body.classList.toggle('crt',S.crt);break;
   case 'newgame':dialog({title:'New Game',icon:URL_.lock,html:'<p>Start a new colony? Your current progress will be erased.</p>',buttons:[{label:'Erase & Restart',fn:newGame},{label:'Cancel'}]});break}});
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('#drone-tog');if(!t||t.disabled)return;S.droneOff=!S.droneOff;log(S.droneOff?'Drones parked. Mining paused.':`Drones back to work on ${ORES[droneOre()].name}.`,'c');renderMine()});
document.addEventListener('change',e=>{if(e.target.id==='dec-target'){L_().target=e.target.value;log(`Auto-Decoder now decoding ${ANIMALS[e.target.value].name}.`,'c')}
  if(e.target.id==='drone-sel'){S.droneOre=e.target.value;S.droneT=[];log(`All drones set to ${ORES[S.droneOre].name}.`,'c');renderMine()}
  if(e.target.dataset&&e.target.dataset.fab!=null){const i=+e.target.dataset.fab;S.fabSlots=S.fabSlots||[];S.fabP=S.fabP||[];S.fabSlots[i]=e.target.value||null;S.fabP[i]=0;log(e.target.value?`Auto Crafter slot ${i+1}: ${NAMES[e.target.value]}.`:`Auto Crafter slot ${i+1} emptied.`,'c');renderRefinery()}});
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-rt]');if(!t)return;S.refTab=t.dataset.rt;renderRefinery()});
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-bay]');if(!b||!AUTO_OK())return;const i=+b.dataset.bay,unl=PLAY_ORES.filter(oreUnlocked),cur=droneTarget(i),nx=unl[(unl.indexOf(cur)+1)%unl.length];S.droneT=S.droneT||[];S.droneT[i]=nx;renderMine()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#startmenu').hidden=true;closeMenus()}});
